1	/* hub_listen: on-Pi stand-in for the hub process on hub.sock.
2	 *
3	 * Purpose: the loopback tests prove the IPC client against a listener in
4	 * the same test process; this program is a real, separate peer, so the
5	 * fault tests on the IPC ladder (Sensor-Pipeline.md, rungs 3-5) can run
6	 * before the hub exists: kill -9 it, kill -STOP it, and feed it from the
7	 * light and soil processes at once. For each message it prints one line:
8	 *   light 42 1234                  a DATA message: sensor, counter, raw value
9	 *   light GAP first=65 count=26    a GAP: counters 65..90 were refused
10	 *   sensor_seq_gap sensor=light expected=43 got=50
11	 *                                  counters 43..49 never arrived, uncovered
12	 * Counters are checked per sensor, and a GAP counts as covering its range,
13	 * so a correct client never produces a sensor_seq_gap line. A bad packet
14	 * prints ipc_bad_message and closes that connection, as the DESIGN.md
15	 * failure-mode table's Hub row says the hub will.
16	 *
17	 * Linux model: an AF_UNIX SOCK_SEQPACKET listener, so each recv() returns
18	 * exactly one message. One thread serves every sensor with poll(), which
19	 * sleeps until the listener or any connection has something to read.
20	 * Nothing is stored and no seq or time is stamped: that's gt_hub_accept's
21	 * job in the real hub. Only one hub_listen can run per socket path: it
22	 * holds an fcntl lock on "<path>.lock" for its whole life, and only the
23	 * lock holder may remove and re-create the socket file (see
24	 * Sensor-Pipeline.md, Decisions; the shared helper is listen_sock.h).
25	 * A second copy exits with
26	 * "already running" and touches nothing.
27	 *
28	 * Usage: hub_listen /run/plantpi/hub.sock    (Ctrl-C to stop) */
29	#include <errno.h>
30	#include <poll.h>
31	#include <stdio.h>
32	#include <string.h>
33	#include <sys/socket.h>
34	#include <unistd.h>
35	
36	#include "ipc.h"
37	#include "listen_sock.h"
38	
39	/* Sensor connections served at once: light and soil, plus room for a
40	 * restarted sensor whose old connection hasn't been noticed closed yet. */
41	#define MAX_SENSOR_CONNS 8
42	
43	/* What the next message from one sensor should carry. Indexed by
44	 * sensor_id; gt_ipc_frame_decode only lets through LIGHT (1) and SOIL (2). */
45	typedef struct {
46	    int      seen;               /* 0 until the first message from this sensor */
47	    uint32_t expected_counter;
48	} counter_track;
49	
50	/* Make sure this is the only hub_listen on `sock_path` (the shared rule in
51	 * listen_sock.h): hold "<sock_path>.lock" for as long as the process runs.
52	 * Holding it is what makes it safe for bind_listener to remove an old
53	 * socket file. Returns the fd that holds the lock (keep it open), or -1
54	 * after printing why. */
55	static int take_instance_lock(const char *sock_path)
56	{
57	    int lock_fd = -1, already_running = 0;
58	    gt_status status = gt_listen_lock(sock_path, &lock_fd, &already_running);
59	    if (status == GT_ERR_INVAL) {
60	        fprintf(stderr, "hub_listen: socket path must be 1..107 characters\n");
61	    } else if (status != GT_OK && already_running) {
62	        fprintf(stderr, "hub_listen: already running on %s (%s.lock is locked)\n",
63	                sock_path, sock_path);
64	    } else if (status != GT_OK) {
65	        fprintf(stderr, "hub_listen: lock %s.lock: %s\n", sock_path, strerror(errno));
66	    }
67	    return status == GT_OK ? lock_fd : -1;
68	}
69	
70	/* Create the listening socket at `path`, replacing a socket file left by a
71	 * hub_listen killed with kill -9 (gt_listen_bind). Call only while holding
72	 * take_instance_lock. The path was already checked by the lock, so
73	 * GT_ERR_INVAL here means something that is not a socket is in the way.
74	 * Returns the listening fd, or -1 after printing why. */
75	static int bind_listener(const char *path)
76	{
77	    int listen_fd = -1;
78	    gt_status status = gt_listen_bind(path, MAX_SENSOR_CONNS, &listen_fd);
79	    if (status == GT_ERR_INVAL) {
80	        fprintf(stderr, "hub_listen: %s exists and is not a socket; not removing it\n", path);
81	    } else if (status != GT_OK) {
82	        fprintf(stderr, "hub_listen: %s: %s\n", path, strerror(errno));
83	    }
84	    return status == GT_OK ? listen_fd : -1;
85	}
86	
87	/* Handle one message on a connection that poll() says is readable. It
88	 * recv()s into a GT_MSG_SIZE + 1 buffer (so an oversized packet shows up
89	 * as 17, not cut to 16) and decodes it as the hub will. A counter other
90	 * than the expected one prints sensor_seq_gap. Then the expectation moves
91	 * past this message: the next counter after DATA, or past the whole
92	 * refused range after a GAP. `tracks` is the caller's array, one entry
93	 * per sensor_id. Returns 1 to keep the connection, or 0 when the sensor
94	 * closed it (recv returned 0) or sent a bad packet; the caller closes it. */
95	static int serve_one(int conn_fd, counter_track *tracks)
96	{
97	    uint8_t buf[GT_MSG_SIZE + 1];
98	    ssize_t len = recv(conn_fd, buf, sizeof buf, 0);
99	    gt_msg message;
100	    gt_status status = gt_ipc_frame_decode(buf, (long)len, &message);
101	    if (status == GT_ERR_IO) {
102	        printf("sensor disconnected (fd %d)\n", conn_fd);
103	        return 0;
104	    }
105	    if (status != GT_OK) {
106	        printf("ipc_bad_message len=%ld (fd %d); closing\n", (long)len, conn_fd);
107	        return 0;
108	    }
109	
110	    const char *sensor_name = message.sensor_id == GT_SENSOR_LIGHT ? "light" : "soil";
111	    counter_track *track = &tracks[message.sensor_id];
112	    if (track->seen && message.counter != track->expected_counter) {
113	        printf("sensor_seq_gap sensor=%s expected=%u got=%u\n", sensor_name,
114	               (unsigned)track->expected_counter, (unsigned)message.counter);
115	    }
116	    if (message.type == GT_MSG_GAP) {
117	        printf("%s GAP first=%u count=%u\n", sensor_name,
118	               (unsigned)message.counter, (unsigned)message.value);
119	        track->expected_counter = message.counter + message.value;
120	    } else {
121	        printf("%s %u %u\n", sensor_name, (unsigned)message.counter, (unsigned)message.value);
122	        track->expected_counter = message.counter + 1;
123	    }
124	    track->seen = 1;
125	    return 1;
126	}
127	
128	/* Take the instance lock, then bind the listening socket at `sock_path`.
129	 * On success stores the lock fd in *lock_fd_out and returns the listening
130	 * fd. On failure returns -1 (after printing why) with no fd left open. */
131	static int lock_then_bind(const char *sock_path, int *lock_fd_out)
132	{
133	    int lock_fd = take_instance_lock(sock_path);
134	    if (lock_fd < 0) {
135	        return -1;
136	    }
137	    int listen_fd = bind_listener(sock_path);
138	    if (listen_fd < 0) {
139	        close(lock_fd);
140	        return -1;
141	    }
142	    *lock_fd_out = lock_fd;
143	    return listen_fd;
144	}
145	
146	/* Serve every sensor connection that poll() marked readable, closing and
147	 * dropping the ones that hung up or sent a bad packet. `conns` is the
148	 * poll() watch list (conns[0] is the listener, skipped here) and
149	 * *conn_count its length; `size_t *` is a pointer so this can shrink the
150	 * caller's count when a connection is dropped. */
151	static void read_ready_sensors(struct pollfd *conns, size_t *conn_count, counter_track *tracks)
152	{
153	    /* Invariant: conns[1..conn_index-1] are open and served this round.
154	     * A closed connection is replaced by the last entry, which is then
155	     * checked in the same slot, so no entry is skipped. */
156	    size_t conn_index = 1;
157	    while (conn_index < *conn_count) {
158	        if ((conns[conn_index].revents & (POLLIN | POLLHUP | POLLERR)) &&
159	            !serve_one(conns[conn_index].fd, tracks)) {
160	            close(conns[conn_index].fd);
161	            conns[conn_index] = conns[*conn_count - 1];
162	            (*conn_count)--;
163	            continue;
164	        }
165	        conn_index++;
166	    }
167	}
168	
169	/* Accept one waiting sensor on `listen_fd` and add it to the watch list,
170	 * or refuse it (close it) when the list is already full. */
171	static void accept_new_sensor(int listen_fd, struct pollfd *conns, size_t *conn_count)
172	{
173	    int conn_fd = accept(listen_fd, NULL, NULL);
174	    if (conn_fd >= 0 && *conn_count < 1 + MAX_SENSOR_CONNS) {
175	        conns[*conn_count].fd = conn_fd;
176	        conns[*conn_count].events = POLLIN;
177	        conns[*conn_count].revents = 0;
178	        (*conn_count)++;
179	        printf("sensor connected (fd %d)\n", conn_fd);
180	    } else if (conn_fd >= 0) {
181	        printf("too many sensor connections; refusing fd %d\n", conn_fd);
182	        close(conn_fd);
183	    }
184	}
185	
186	/* Listen, then serve every sensor from one poll() loop until killed.
187	 * `struct pollfd` is one entry in poll()'s watch list: `fd` is what to
188	 * watch, `events` what to wait for (POLLIN: something to read), and the
189	 * kernel fills in `revents` with what actually happened (POLLIN, or
190	 * POLLHUP / POLLERR when the peer is gone). poll() sleeps until at least
191	 * one entry has revents set, so an idle hub_listen uses no CPU.
192	 * conns[0] is always the listener; conns[1..conn_count-1] are sensors. */
193	int main(int argc, char **argv)
194	{
195	    /* Line-buffer stdout so each message line appears at once, even when
196	     * the output is piped to a log (e.g. `| tee hub.log`). */
197	    setvbuf(stdout, NULL, _IOLBF, 0);
198	
199	    if (argc != 2) {
