1	#ifndef FAKE_SOCK_H
2	#define FAKE_SOCK_H
3	
4	/* Fake gt_sock_ops for IPC client tests: no socket, no hub, no waiting.
5	 *
6	 * A test declares a fake_sock on the stack, passes fake_sock_ops(&f) and &f
7	 * to gt_ipc_client_open_ops, scripts connect failures and send results,
8	 * then inspects what the client did: connect attempts, frames sent,
9	 * disconnects and the final destroy. The fake is the ctx and is owned by
10	 * the test, so destroy() only counts and never frees. fake_sock_ops()
11	 * zeroes the fake, so call it before scripting anything.
12	 *
13	 * Header-only (static inline) for the same reason as fake_i2c.h: the
14	 * Makefile links each test .c with src/ only, and inline keeps unused
15	 * helpers from tripping -Werror. */
16	#include <stddef.h>
17	#include <stdint.h>
18	#include <string.h>
19	
20	#include "ipc_sock.h"
21	
22	#define FAKE_SOCK_MAX_SENT    256   /* enough for two full rings plus GAPs */
23	#define FAKE_SOCK_MAX_RESULTS 64
24	
25	typedef struct {
26	    /* connect(): the next fail_connects calls return GT_ERR_IO. */
27	    int      connect_calls;
28	    int      fail_connects;
29	    int      connected;
30	
31	    /* send(): scripted results, used front to back, one per call; once
32	     * they run out every send returns GT_OK. */
33	    gt_status send_results[FAKE_SOCK_MAX_RESULTS];
34	    size_t    n_send_results;
35	    size_t    send_result_pos;
36	    int       send_calls;
37	
38	    /* Every frame send() returned GT_OK for, in order: what the hub got. */
39	    uint8_t  sent[FAKE_SOCK_MAX_SENT][GT_MSG_SIZE];
40	    size_t   n_sent;
41	
42	    int      disconnect_calls;
43	    int      destroy_calls;
44	
45	    /* Client bugs the fake can see; a correct client leaves these at 0. */
46	    int      connect_while_connected;
47	    int      send_while_disconnected;
48	    int      wrong_len_sends;   /* a send() whose len wasn't GT_MSG_SIZE */
49	} fake_sock;
50	
51	/* Script the result of a later send() call: results are used in the order
52	 * they're pushed. GT_ERR_FULL acts like EAGAIN (hub alive, buffer full),
53	 * GT_ERR_IO like EPIPE (hub gone). Extra pushes past the cap are ignored. */
54	static inline void fake_sock_push_send_result(fake_sock *fake, gt_status result)
55	{
56	    if (fake->n_send_results < FAKE_SOCK_MAX_RESULTS) {
57	        fake->send_results[fake->n_send_results++] = result;
58	    }
59	}
60	
61	/* Count the attempt; fail it while fail_connects is above 0, otherwise the
62	 * fake is connected from now until disconnect(). */
63	static inline gt_status fake_sock_connect(void *ctx)
64	{
65	    fake_sock *fake = ctx;
66	    fake->connect_calls++;
67	    if (fake->connected) {
68	        fake->connect_while_connected++;
69	    }
70	    if (fake->fail_connects > 0) {
71	        fake->fail_connects--;
72	        return GT_ERR_IO;
73	    }
74	    fake->connected = 1;
75	    return GT_OK;
76	}
77	
78	/* Return the next scripted result (GT_OK once the script runs out). Only a
79	 * GT_OK send is recorded in sent[], because only then did the kernel take
80	 * the frame. A GT_ERR_IO result doesn't disconnect the fake by itself: the
81	 * client is expected to call disconnect(), and a send after that counts as
82	 * send_while_disconnected. */
83	static inline gt_status fake_sock_send(void *ctx, const uint8_t *buf, size_t len)
84	{
85	    fake_sock *fake = ctx;
86	    fake->send_calls++;
87	    if (!fake->connected) {
88	        fake->send_while_disconnected++;
89	        return GT_ERR_IO;
90	    }
91	    if (len != GT_MSG_SIZE) {
92	        fake->wrong_len_sends++;
93	    }
94	
95	    gt_status result = GT_OK;
96	    if (fake->send_result_pos < fake->n_send_results) {
97	        result = fake->send_results[fake->send_result_pos++];
98	    }
99	    if (result == GT_OK && fake->n_sent < FAKE_SOCK_MAX_SENT) {
100	        size_t copy_len = len < GT_MSG_SIZE ? len : GT_MSG_SIZE;
101	        memcpy(fake->sent[fake->n_sent], buf, copy_len);
102	        fake->n_sent++;
103	    }
104	    return result;
105	}
106	
107	/* Drop the connection; the fake stays usable for the next connect(). */
108	static inline void fake_sock_disconnect(void *ctx)
109	{
110	    fake_sock *fake = ctx;
111	    fake->disconnect_calls++;
112	    fake->connected = 0;
113	}
114	
115	/* Count only: the test owns the fake, so there is nothing to free. A
116	 * correct client calls this exactly once (ICC-01). */
117	static inline void fake_sock_destroy(void *ctx)
118	{
119	    fake_sock *fake = ctx;
120	    fake->destroy_calls++;
121	    fake->connected = 0;
122	}
123	
124	/* Reset `fake` and return the ops that route every call to it. Pass
125	 * `fake` itself as the ctx: gt_ipc_client_open_ops(fake_sock_ops(&f), &f). */
126	static inline const gt_sock_ops *fake_sock_ops(fake_sock *fake)
127	{
128	    static const gt_sock_ops ops = {
129	        .connect    = fake_sock_connect,
130	        .send       = fake_sock_send,
131	        .disconnect = fake_sock_disconnect,
132	        .destroy    = fake_sock_destroy,
133	    };
134	    memset(fake, 0, sizeof *fake);
135	    return &ops;
136	}
137	
138	#endif
139

