1	/* Linux AF_UNIX implementation of the gt_sock_ops seam (see ipc_sock.h).
2	 *
3	 * Purpose: this file is the only place that makes socket system calls. It
4	 * moves whole 16 B frames from a sensor process to hub.sock and turns what
5	 * the kernel says into a gt_status. It knows nothing about rings, backoff
6	 * or GAPs: that policy lives in the client (ipc_client.c), which reaches
7	 * this file only through the ops table, so tests can swap in
8	 * tests/fake_sock.h.
9	 *
10	 * Linux model: the socket is AF_UNIX SOCK_SEQPACKET, so the kernel keeps
11	 * message boundaries: one send() is one whole message and the hub's recv()
12	 * gets exactly that message. Every call is non-blocking (SOCK_NONBLOCK),
13	 * so a slow or frozen hub returns EAGAIN instead of stalling the 1 Hz
14	 * sampler, and send() passes MSG_NOSIGNAL, so a dead hub is the error
15	 * EPIPE instead of a SIGPIPE signal that would kill the sensor process.
16	 * How errno maps to a gt_status:
17	 *   connect: any failure (ENOENT: no socket file; ECONNREFUSED: file but
18	 *            no hub listening; EAGAIN: the hub's backlog is full) -> GT_ERR_IO
19	 *   send:    EAGAIN -> GT_ERR_FULL; EPIPE, ECONNRESET, anything else -> GT_ERR_IO */
20	#include "ipc_sock.h"
21	
22	#include <errno.h>
23	#include <stdlib.h>
24	#include <string.h>
25	#include <sys/socket.h>
26	#include <sys/un.h>
27	#include <unistd.h>
28	
29	/* Per-client state, passed to every op as the opaque `ctx`. The address is
30	 * built once in gt_ipc_sock_linux and reused by every reconnect.
31	 * `struct sockaddr_un` is the AF_UNIX address type: a family field plus
32	 * the socket file's path in a fixed 108-byte array (sun_path). */
33	typedef struct {
34	    struct sockaddr_un addr;
35	    int                fd;     /* the connected socket, or -1 when not connected */
36	} linux_sock;
37	
38	/* Open a fresh socket and connect it to the hub. connect() takes a generic
39	 * `struct sockaddr *`, so the AF_UNIX address goes through a cast; the
40	 * kernel reads its family field to know the real type. On a non-blocking
41	 * AF_UNIX socket, connect either finishes at once or fails at once, so
42	 * there's nothing to wait for. Any failure closes the new fd and is
43	 * GT_ERR_IO, with no retry here, not even on EINTR: the client retries
44	 * after its backoff wait. Already connected is GT_OK and changes nothing.
45	 * SOCK_CLOEXEC closes the fd automatically if this process ever exec()s
46	 * another program, so the socket can't leak into it. */
47	static gt_status sock_connect(void *ctx)
48	{
49	    linux_sock *sock = ctx;
50	    if (sock->fd >= 0) {
51	        return GT_OK;
52	    }
53	    int fd = socket(AF_UNIX, SOCK_SEQPACKET | SOCK_NONBLOCK | SOCK_CLOEXEC, 0);
54	    if (fd < 0) {
55	        return GT_ERR_IO;
56	    }
57	    if (connect(fd, (const struct sockaddr *)&sock->addr, sizeof sock->addr) != 0) {
58	        close(fd);
59	        return GT_ERR_IO;
60	    }
61	    sock->fd = fd;
62	    return GT_OK;
63	}
64	
65	/* Send one whole frame. A SEQPACKET send is all or nothing, so anything
66	 * but exactly `len` bytes is a failure. EINTR (a signal arrived before
67	 * anything was sent) is simply tried again. EAGAIN means the hub is alive
68	 * but hasn't recv()d fast enough, so its buffer is full: GT_ERR_FULL, and
69	 * the client keeps the frame. Everything else, including EPIPE and
70	 * ECONNRESET when the hub is gone, is GT_ERR_IO. Not connected is
71	 * GT_ERR_IO too. */
72	static gt_status sock_send(void *ctx, const uint8_t *buf, size_t len)
73	{
74	    linux_sock *sock = ctx;
75	    if (sock->fd < 0) {
76	        return GT_ERR_IO;
77	    }
78	    ssize_t sent;
79	    /* Repeat only while a signal interrupted the call before it sent anything. */
80	    do {
81	        sent = send(sock->fd, buf, len, MSG_NOSIGNAL);
82	    } while (sent < 0 && errno == EINTR);
83	
84	    if (sent == (ssize_t)len) {
85	        return GT_OK;
86	    }
87	    if (sent < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
88	        return GT_ERR_FULL;
89	    }
90	    return GT_ERR_IO;
91	}
92	
93	/* Close the current connection but keep the ctx and its address, so the
94	 * next connect makes a fresh socket. Called by the client when send says
95	 * the hub is gone. Safe when not connected. */
96	static void sock_disconnect(void *ctx)
97	{
98	    linux_sock *sock = ctx;
99	    if (sock->fd >= 0) {
100	        close(sock->fd);
101	        sock->fd = -1;
102	    }
103	}
104	
105	/* Close any connection and free the ctx. gt_ipc_client_close calls this
106	 * exactly once; the ctx must not be used after. */
107	static void sock_destroy(void *ctx)
108	{
109	    sock_disconnect(ctx);
110	    free(ctx);
111	}
112	
113	/* The real implementation of the seam. The functions above are static, so
114	 * the rest of the program can reach them only through this table. */
115	static const gt_sock_ops linux_ops = {
116	    .connect    = sock_connect,
117	    .send       = sock_send,
118	    .disconnect = sock_disconnect,
119	    .destroy    = sock_destroy,
120	};
121	
122	/* Prepare a ctx for the hub socket at `path`; no socket is opened yet.
123	 * The path must fit in sun_path with its closing '\0', so its length must
124	 * be under sizeof addr.sun_path (108): GT_ERR_INVAL otherwise, or for NULL
125	 * args or an empty path. GT_ERR_NOMEM if the ctx can't be allocated. The
126	 * address is checked and built before anything is allocated, so every
127	 * failure leaves the outputs untouched with nothing to undo. */
128	gt_status gt_ipc_sock_linux(const char *path, const gt_sock_ops **ops_out, void **ctx_out)
129	{
130	    if (path == NULL || ops_out == NULL || ctx_out == NULL) {
131	        return GT_ERR_INVAL;
132	    }
133	    struct sockaddr_un addr;
134	    memset(&addr, 0, sizeof addr);
135	    size_t path_len = strlen(path);
136	    if (path_len == 0 || path_len >= sizeof addr.sun_path) {
137	        return GT_ERR_INVAL;
138	    }
139	    addr.sun_family = AF_UNIX;
140	    memcpy(addr.sun_path, path, path_len + 1);
141	
142	    linux_sock *sock = malloc(sizeof *sock);
143	    if (sock == NULL) {
144	        return GT_ERR_NOMEM;
145	    }
146	    sock->addr = addr;
147	    sock->fd = -1;
148	
149	    *ops_out = &linux_ops;
150	    *ctx_out = sock;
151	    return GT_OK;
152	}
153

1	/* storage_feed: a load generator standing in for the hub on storage.sock
2	 * (DESIGN.md Evaluation plan, Test tooling: "writes synthetic records into
3	 * storage.sock at a set rate").
4	 *
5	 * Purpose: drive storage_main before the hub exists. It connects, reads
6	 * the seq_resume reply, and sends `count` light DATA records continuing
7	 * from the next seq, exactly as a freshly started hub will (gt_next_seq):
8	 * seq resume + 1 onward, or 0 on an empty log. It prints the reply and
9	 * what it sent, so a run shows whether storage kept every record across
10	 * a SIGTERM restart (the reply continues where the last run ended) or a
11	 * kill -9 (the reply is the last committed seq; a fresh sender continues
12	 * from there, so the lost seqs are simply reused, not marked as a GAP).
13	 *
14	 * stdout is line-buffered, so each line reaches a file or pipe as soon
15	 * as it is printed (a script can read the reply while the feed runs).
16	 *
17	 * Linux model: an AF_UNIX SOCK_SEQPACKET client, so each send() is one
18	 * whole 24 B record. MSG_NOSIGNAL turns a storage that went away into an
19	 * error instead of a SIGPIPE.
20	 *
21	 * With -r it acts as a hub that keeps running while storage restarts:
22	 * when a send fails it prints "storage gone after seq K", reconnects
23	 * every 100 ms, and continues from max(own next seq, reply + 1), so seqs
24	 * a kill -9 lost leave a hole that storage covers with a GAP (PF-03).
25	 * COUNT is then the total over all connections, and 0 means no limit.
26	 * SIGTERM / SIGINT stop the feed cleanly: it still prints its final
27	 * "sent N records, seq A..B" line (exit 0 with -r).
28	 *
29	 * Usage: storage_feed [-r] /run/plantpi/storage.sock COUNT [RATE_HZ]
30	 *   RATE_HZ defaults to 10; 0 sends as fast as possible. */
31	#include <errno.h>
32	#include <poll.h>
33	#include <signal.h>
34	#include <stdio.h>
35	#include <stdlib.h>
36	#include <string.h>
37	#include <sys/socket.h>
38	#include <sys/un.h>
39	#include <time.h>
40	#include <unistd.h>
41	
42	#include "log_record.h"
43	#include "storage_proto.h"
44	
45	#define REPLY_WAIT_MS 2000
46	
47	/* Set by SIGTERM / SIGINT. sig_atomic_t is the integer type a signal
48	 * handler may safely write; volatile makes the loop re-read it each pass. */
49	static volatile sig_atomic_t stop_requested = 0;
50	
51	/* Only sets the flag: printing or closing here would not be signal-safe. */
52	static void on_stop(int signo)
53	{
54	    (void)signo;
55	    stop_requested = 1;
56	}
57	
58	/* Parse a whole non-negative decimal number. Returns 1 on success. */
59	static int parse_count(const char *text, unsigned long *value_out)
60	{
61	    char *end = NULL;
62	    errno = 0;
63	    unsigned long value = strtoul(text, &end, 10);
64	    if (errno != 0 || end == text || *end != '\0' || text[0] == '-') {
65	        return 0;
66	    }
67	    *value_out = value;
68	    return 1;
69	}
70	
71	/* Connect to storage.sock. Returns the fd, or -1 after printing why
72	 * (unless quiet is set). */
73	static int connect_storage(const char *path, int quiet)
74	{
75	    struct sockaddr_un addr;
76	    memset(&addr, 0, sizeof addr);
77	    if (strlen(path) >= sizeof addr.sun_path) {
78	        fprintf(stderr, "storage_feed: socket path too long\n");
79	        return -1;
80	    }
81	    addr.sun_family = AF_UNIX;
82	    memcpy(addr.sun_path, path, strlen(path) + 1);
83	    int fd = socket(AF_UNIX, SOCK_SEQPACKET, 0);
84	    if (fd < 0 || connect(fd, (const struct sockaddr *)&addr, sizeof addr) != 0) {
85	        if (!quiet) {
86	            fprintf(stderr, "storage_feed: %s: %s\n", path, strerror(errno));
87	        }
88	        if (fd >= 0) {
89	            close(fd);
90	        }
91	        return -1;
92	    }
93	    return fd;
94	}
95	
96	/* Wait for and decode the seq_resume reply. Returns 1 on success. */
97	static int read_resume(int fd, gt_resume *resume)
98	{
99	    struct pollfd wait_for = { .fd = fd, .events = POLLIN, .revents = 0 };
100	    uint8_t reply[GT_RESUME_SIZE + 1];
101	    if (poll(&wait_for, 1, REPLY_WAIT_MS) != 1) {
102	        fprintf(stderr, "storage_feed: no seq_resume reply within %d ms\n", REPLY_WAIT_MS);
103	        return 0;
104	    }
105	    ssize_t got = recv(fd, reply, sizeof reply, 0);
106	    if (got != GT_RESUME_SIZE || gt_resume_decode(reply, resume) != GT_OK) {
107	        fprintf(stderr, "storage_feed: bad seq_resume reply (%ld bytes)\n", (long)got);
108	        return 0;
109	    }
110	    return 1;
111	}
112	
113	/* Connect, read seq_resume, pick the next seq with gt_next_seq and print
114	 * the usual "seq_resume: ..." line. has_own/own_next are passed straight
115	 * to gt_next_seq. quiet hides connect errors (reconnect mode expects them
116	 * while storage is down). Returns the fd, or -1 on any failure. */
117	static int open_session(const char *path, int quiet, int has_own,
118	                        uint32_t own_next, uint32_t *next_out)
119	{
120	    int fd = connect_storage(path, quiet);
121	    gt_resume resume;
122	    if (fd < 0 || !read_resume(fd, &resume)) {
123	        if (fd >= 0) {
124	            close(fd);
125	        }
126	        return -1;
127	    }
128	    if (gt_next_seq(has_own, own_next, &resume, next_out) != GT_OK) {
129	        fprintf(stderr, "storage_feed: no next seq after %lu\n", (unsigned long)resume.seq);
130	        close(fd);
131	        return -1;
132	    }
133	    if (resume.has_last) {
134	        printf("seq_resume: last=%lu, sending from %lu\n", (unsigned long)resume.seq,
135	               (unsigned long)*next_out);
136	    } else {
137	        printf("seq_resume: empty log, sending from %lu\n", (unsigned long)*next_out);
138	    }
139	    return fd;
140	}
141	
142	/* Wall-clock time in us since the epoch, stamped into each record as the
143	 * hub would. */
144	static uint64_t wall_us(void)
145	{
146	    struct timespec now;
147	    clock_gettime(CLOCK_REALTIME, &now);
148	    return (uint64_t)now.tv_sec * 1000000u + (uint64_t)now.tv_nsec / 1000u;
149	}
150	
151	/* What one pass of the send loop came to. An enum gives names to a small
152	 * set of int values, so the caller compares against FEED_STOP rather than
153	 * a bare number. */
154	typedef enum { FEED_SENT, FEED_RETRY, FEED_STOP } feed_result;
155	
156	/* Everything the send loop changes as it goes, in one struct so a helper
157	 * can update it through a single pointer. */
158	typedef struct {
159	    int           fd;          /* the connection to storage; -1 if none */
160	    uint32_t      own_next;    /* the next seq to send */
161	    uint32_t      first_seq;   /* the first seq sent (valid once sent > 0) */
162	    unsigned long sent;        /* records sent, over all connections */
163	} feed_state;
164	
165	/* One pass of the send loop: connect first if there is no connection
166	 * (only with -r), then send the record with seq state->own_next.
167	 *   FEED_SENT:  it went; own_next and sent moved on.
168	 *   FEED_RETRY: storage is not up yet or went away (only with -r); the
169	 *               next pass reconnects.
170	 *   FEED_STOP:  give up: a send failed without -r, or encoding failed. */
171	static feed_result send_next(feed_state *state, const char *sock_path, int reconnect)
172	{
173	    if (state->fd < 0) {
174	        state->fd = open_session(sock_path, 1, state->sent > 0, state->own_next,
175	                                 &state->own_next);
176	        if (state->fd < 0) {
177	            const struct timespec retry_wait = { 0, 100000000L }; /* 100 ms */
178	            nanosleep(&retry_wait, NULL);
179	            return FEED_RETRY;
180	        }
181	    }
182	    const gt_record record = {
183	        .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT,
184	        .seq = state->own_next, .timestamp_us = wall_us(),
185	        .value = (uint32_t)state->sent,
186	    };
187	    uint8_t wire[GT_REC_SIZE];
188	    if (gt_record_encode(&record, wire) != GT_OK) {
189	        fprintf(stderr, "storage_feed: encode seq %lu failed\n", (unsigned long)record.seq);
190	        return FEED_STOP;
191	    }
192	    if (send(state->fd, wire, sizeof wire, MSG_NOSIGNAL) != (ssize_t)sizeof wire) {
193	        if (!reconnect) {
194	            fprintf(stderr, "storage_feed: send seq %lu: %s\n",
195	                    (unsigned long)record.seq, strerror(errno));
196	            return FEED_STOP;
197	        }
198	        if (state->sent > 0) {
199	            printf("storage gone after seq %lu\n", (unsigned long)(state->own_next - 1));
200	        } else {
201	            printf("storage gone before any seq\n");
202	        }
203	        close(state->fd);
204	        state->fd = -1;
205	        return FEED_RETRY;
206	    }
207	    if (state->sent == 0) {
208	        state->first_seq = state->own_next;
209	    }
210	    state->own_next++;
211	    state->sent++;
212	    return FEED_SENT;
213	}
214	
215	/* The command line, parsed. */
216	typedef struct {
217	    int           reconnect;   /* 1 if -r was given */
218	    const char   *sock_path;
219	    unsigned long count;       /* records to send; 0 with -r means no limit */
220	    unsigned long rate_hz;     /* sends per second; 0 means as fast as possible */
221	} feed_opts;
222	
223	/* Route SIGTERM and SIGINT to on_stop. No SA_RESTART: a stop signal cuts
224	 * nanosleep/poll short (EINTR), so the loop sees stop_requested at once. */
225	static void install_stop_handlers(void)
226	{
227	    struct sigaction stop_action;
228	    memset(&stop_action, 0, sizeof stop_action);
229	    stop_action.sa_handler = on_stop;
230	    sigemptyset(&stop_action.sa_mask);
231	    sigaction(SIGTERM, &stop_action, NULL);
232	    sigaction(SIGINT, &stop_action, NULL);
233	}
234	
235	/* Parse "[-r] SOCK COUNT [RATE_HZ]" into `opts`. Returns 1 on success, or
236	 * 0 after printing usage. */
237	static int parse_feed_args(int argc, char **argv, feed_opts *opts)
238	{
239	    /* -r, if given, comes first; arg_base is then the index of SOCK. */
240	    opts->reconnect = argc > 1 && strcmp(argv[1], "-r") == 0;
241	    int arg_base = opts->reconnect ? 2 : 1;
242	    int args_left = argc - arg_base;
243	    opts->sock_path = argv[arg_base];
244	    opts->count = 0;
245	    opts->rate_hz = 10;
246	    if ((args_left != 2 && args_left != 3) || !parse_count(argv[arg_base + 1], &opts->count)
247	        || (args_left == 3 && !parse_count(argv[arg_base + 2], &opts->rate_hz))) {
248	        fprintf(stderr, "usage: %s [-r] /run/plantpi/storage.sock COUNT [RATE_HZ]\n",
249	                argv[0]);
250	        return 0;
251	    }
252	    return 1;
253	}
254	
255	/* The pause between sends for `rate_hz` sends per second (zero for 0). */
256	static struct timespec rate_to_delay(unsigned long rate_hz)
257	{
258	    struct timespec delay = { 0, 0 };
259	    if (rate_hz > 0) {
260	        delay.tv_sec = (time_t)(1 / rate_hz);
261	        delay.tv_nsec = (long)((1000000000ul / rate_hz) % 1000000000ul);
262	    }
263	    return delay;
264	}
265	
266	/* 1 while the send loop should go on: no stop signal yet, and either -r
267	 * with no limit or fewer than COUNT records sent. */
268	static int should_keep_sending(const feed_opts *opts, const feed_state *state)
269	{
270	    return !stop_requested && ((opts->reconnect && opts->count == 0) || state->sent < opts->count);
271	}
272	
273	/* Print the final "sent N records" line, close the connection if one is
274	 * open, and return the exit code: 0 if all COUNT records went, or if -r
275	 * was stopped by a signal; 1 otherwise. */
276	static int close_and_report(feed_state *state, const feed_opts *opts)
277	{
278	    if (state->sent > 0) {
279	        printf("sent %lu records, seq %lu..%lu\n", state->sent, (unsigned long)state->first_seq,
280	               (unsigned long)(state->own_next - 1));
281	    } else {
282	        printf("sent 0 records\n");
283	    }
284	    if (state->fd >= 0) {
285	        close(state->fd);
286	    }
287	    return (state->sent == opts->count || (opts->reconnect && stop_requested)) ? 0 : 1;
288	}
289	
290	int main(int argc, char **argv)
291	{
292	    /* _IOLBF = line buffering: flush stdout at every '\n', even when it is
293	     * redirected to a file (the default there is to hold it until exit). */
294	    setvbuf(stdout, NULL, _IOLBF, 0);
295	    install_stop_handlers();
296	    feed_opts opts;
297	    if (!parse_feed_args(argc, argv, &opts)) {
298	        return 2;
299	    }
300	
301	    struct timespec delay = rate_to_delay(opts.rate_hz);
302	    feed_state state = { .fd = -1, .own_next = 0, .first_seq = 0, .sent = 0 };
303	    if (!opts.reconnect) {
304	        state.fd = open_session(opts.sock_path, 0, 0, 0, &state.own_next);
305	        if (state.fd < 0) {
306	            return 1;
307	        }
308	    }
309	    /* invariant: every seq below state.own_next was sent exactly once; none
310	     * is reused */
311	    while (should_keep_sending(&opts, &state)) {
312	        feed_result result = send_next(&state, opts.sock_path, opts.reconnect);
313	        if (result == FEED_STOP) {
314	            break;
315	        }
316	        if (result == FEED_SENT && opts.rate_hz > 0) {
317	            nanosleep(&delay, NULL);
318	        }
319	    }
320	    return close_and_report(&state, &opts);
321	}
