1	/* Unit tests for picking the next seq after a seq_resume reply
2	 * (src/storage_proto.c): gt_next_seq.
3	 *
4	 * Purpose: prove the PF-03 numbering rule, next = max(own next, reply + 1).
5	 * A fresh sender (the hub just started, or storage_feed without -r) takes
6	 * the reply + 1, or 0 on an empty log. A running sender keeps its own
7	 * counter, so seqs storage lost in a kill -9 leave a hole that storage
8	 * turns into a GAP. The output is untouched on every failure. Pure
9	 * arithmetic: no sockets. Run under make test / asan / memcheck.
10	 * Implements NSQ-01 through NSQ-08.
11	 *
12	 * What these tests cannot prove: that storage writes the GAP for the hole
13	 * (SAP / SQG do) or that the senders call this (the fault rounds do). */
14	#include <stdint.h>
15	
16	#include "check.h"
17	#include "storage_proto.h"
18	
19	/* Value the output is pre-filled with, to show a failure leaves it alone. */
20	#define UNTOUCHED 0x5A5A5A5Au
21	
22	/* ---- NSQ-01: fresh sender continues after reply ----
23	 * own_next is 999 to prove a fresh sender ignores it. */
24	static void test_nsq01_fresh_after_reply(void)
25	{
26	    const gt_resume resume = { .has_last = 1, .seq = 59 };
27	    uint32_t next = UNTOUCHED;
28	
29	    CHECK_EQ(gt_next_seq(0, 999, &resume, &next), GT_OK);
30	    CHECK_EQ(next, 60);
31	}
32	
33	/* ---- NSQ-02: fresh sender on an empty log starts at 0 ---- */
34	static void test_nsq02_fresh_empty_log(void)
35	{
36	    const gt_resume resume = { .has_last = 0, .seq = 0 };
37	    uint32_t next = UNTOUCHED;
38	
39	    CHECK_EQ(gt_next_seq(0, 999, &resume, &next), GT_OK);
40	    CHECK_EQ(next, 0);
41	}
42	
43	/* ---- NSQ-03: running sender keeps its counter past a loss ----
44	 * It sent up to 79, storage was killed and kept only up to 59: the next
45	 * seq is 80, so storage sees 60-79 missing and writes their GAP. */
46	static void test_nsq03_running_keeps_counter(void)
47	{
48	    const gt_resume resume = { .has_last = 1, .seq = 59 };
49	    uint32_t next = UNTOUCHED;
50	
51	    CHECK_EQ(gt_next_seq(1, 80, &resume, &next), GT_OK);
52	    CHECK_EQ(next, 80);
53	}
54	
55	/* ---- NSQ-04: running sender after a clean restart ----
56	 * Storage kept everything (SIGTERM), so both sides agree on 60: no hole. */
57	static void test_nsq04_running_clean_restart(void)
58	{
59	    const gt_resume resume = { .has_last = 1, .seq = 59 };
60	    uint32_t next = UNTOUCHED;
61	
62	    CHECK_EQ(gt_next_seq(1, 60, &resume, &next), GT_OK);
63	    CHECK_EQ(next, 60);
64	}
65	
66	/* ---- NSQ-05: a reply ahead of the counter wins ----
67	 * Storage already holds up to 59 (another sender filled it), so reusing
68	 * 10.. would only be rejected as old: continue at 60. */
69	static void test_nsq05_reply_ahead_wins(void)
70	{
71	    const gt_resume resume = { .has_last = 1, .seq = 59 };
72	    uint32_t next = UNTOUCHED;
73	
74	    CHECK_EQ(gt_next_seq(1, 10, &resume, &next), GT_OK);
75	    CHECK_EQ(next, 60);
76	}
77	
78	/* ---- NSQ-06: running sender on an empty log keeps its counter ----
79	 * The log was wiped under a running sender: there is no reply seq, so
80	 * the sender's own counter is the only one. */
81	static void test_nsq06_running_empty_log(void)
82	{
83	    const gt_resume resume = { .has_last = 0, .seq = 0 };
84	    uint32_t next = UNTOUCHED;
85	
86	    CHECK_EQ(gt_next_seq(1, 80, &resume, &next), GT_OK);
87	    CHECK_EQ(next, 80);
88	}
89	
90	/* ---- NSQ-07: NULL arguments are rejected ---- */
91	static void test_nsq07_null_args(void)
92	{
93	    const gt_resume resume = { .has_last = 1, .seq = 59 };
94	    uint32_t next = UNTOUCHED;
95	
96	    CHECK_EQ(gt_next_seq(1, 80, NULL, &next), GT_ERR_INVAL);
97	    CHECK_EQ(next, UNTOUCHED);
98	    CHECK_EQ(gt_next_seq(1, 80, &resume, NULL), GT_ERR_INVAL);
99	}
100	
101	/* ---- NSQ-08: a reply of UINT32_MAX has no next seq ----
102	 * reply + 1 would wrap to 0, which storage would reject as old. Checked
103	 * for a fresh and a running sender. */
104	static void test_nsq08_reply_at_max(void)
105	{
106	    const gt_resume resume = { .has_last = 1, .seq = UINT32_MAX };
107	    uint32_t next = UNTOUCHED;
108	
109	    CHECK_EQ(gt_next_seq(0, 0, &resume, &next), GT_ERR_FULL);
110	    CHECK_EQ(next, UNTOUCHED);
111	    CHECK_EQ(gt_next_seq(1, 80, &resume, &next), GT_ERR_FULL);
112	    CHECK_EQ(next, UNTOUCHED);
113	}
114	
115	static const test_case_t tests[] = {
116	    {"NSQ-01", "fresh sender continues after reply", test_nsq01_fresh_after_reply},
117	    {"NSQ-02", "fresh sender on an empty log starts at 0", test_nsq02_fresh_empty_log},
118	    {"NSQ-03", "running sender keeps its counter past a loss", test_nsq03_running_keeps_counter},
119	    {"NSQ-04", "running sender after a clean restart", test_nsq04_running_clean_restart},
120	    {"NSQ-05", "a reply ahead of the counter wins", test_nsq05_reply_ahead_wins},
121	    {"NSQ-06", "running sender on an empty log", test_nsq06_running_empty_log},
122	    {"NSQ-07", "NULL arguments are rejected", test_nsq07_null_args},
123	    {"NSQ-08", "a reply of UINT32_MAX has no next seq", test_nsq08_reply_at_max},
124	};
125	
126	int main(void)
127	{
128	    return RUN_TESTS(tests);
129	}
