    uint32_t next = UNTOUCHED;

    CHECK_EQ(gt_next_seq(0, 999, &resume, &next), GT_OK);
    CHECK_EQ(next, 60);
}

/* ---- NSQ-02: fresh sender on an empty log starts at 0 ---- */
static void test_nsq02_fresh_empty_log(void)
{
    const gt_resume resume = { .has_last = 0, .seq = 0 };
    uint32_t next = UNTOUCHED;

    CHECK_EQ(gt_next_seq(0, 999, &resume, &next), GT_OK);
    CHECK_EQ(next, 0);
