1	#ifndef CHECK_H
2	#define CHECK_H
3	
4	/* Minimal test checks. Each failing check prints file:line and is counted;
5	 * tests keep running so one run reports every failure. A test file lists
6	 * its cases in a test_case_t table and its main() is
7	 * `return RUN_TESTS(tests);`, which prints [ID] name PASS/FAIL per case
8	 * and gives make test / CI a nonzero exit if any case failed. */
9	#include <stddef.h>
10	#include <stdio.h>
11	
12	static int check_failures;
13	
14	#define CHECK(cond)                                                     \
15	    do {                                                                \
16	        if (!(cond)) {                                                  \
17	            fprintf(stderr, "    %s:%d: CHECK failed: %s\n",            \
18	                    __FILE__, __LINE__, #cond);                         \
19	            check_failures++;                                           \
20	        }                                                               \
21	    } while (0)
22	
23	/* Integer equality; prints both values on failure. */
24	#define CHECK_EQ(a, b)                                                  \
25	    do {                                                                \
26	        long long check_a_ = (long long)(a);                            \
27	        long long check_b_ = (long long)(b);                            \
28	        if (check_a_ != check_b_) {                                     \
29	            fprintf(stderr, "    %s:%d: CHECK_EQ failed: %s == %s "     \
30	                    "(%lld vs %lld)\n", __FILE__, __LINE__, #a, #b,     \
31	                    check_a_, check_b_);                                \
32	            check_failures++;                                           \
33	        }                                                               \
34	    } while (0)
35	
36	/* One case: an ID like "LSO-03", a short name, and a void test body. */
37	typedef struct {
38	    const char *id;
39	    const char *name;
40	    void (*run)(void);
41	} test_case_t;
42	
43	/* Run every case in order. A case passes if it added no failures; the
44	 * count is snapshotted, never reset, so a later failure cannot flip an
45	 * earlier verdict. Flushing keeps a case's diagnostics above its line.
46	 * inline so files not yet using it don't trip -Wunused-function. */
47	static inline int run_tests(const test_case_t *t, size_t n)
48	{
49	    size_t passed = 0;
50	    for (size_t i = 0; i < n; i++) {
51	        int before = check_failures;
52	        t[i].run();
53	        int ok = (check_failures == before);
54	        fflush(stderr);
55	        printf("[%s] %-45s %s\n", t[i].id, t[i].name, ok ? "PASS" : "FAIL");
56	        fflush(stdout);
57	        if (ok) {
58	            passed++;
59	        }
60	    }
61	    printf("%zu/%zu tests passed\n", passed, n);
62	    return passed == n ? 0 : 1;
63	}
64	
65	#define RUN_TESTS(tbl) run_tests((tbl), sizeof(tbl) / sizeof((tbl)[0]))
66	
67	#endif
