105	    client->backoff_ms = GT_IPC_BACKOFF_MIN_MS;
106	    if (client->had_trouble) {
107	        client->had_trouble = 0;
108	        client->stats.reconnects++;
109	        *events |= GT_IPC_EV_RECONNECT;
110	    }
111	    return 1;
112	}
113	
114	/* Connect if needed, then hand frames to the socket oldest first until the
115	 * ring is empty or the socket says stop. A frame leaves the ring only once
116	 * send returns GT_OK, i.e. the kernel has taken it. Any other result keeps
117	 * that frame at the head for the next drain:
118	 *   GT_ERR_FULL (EAGAIN): the hub is alive but its buffer is full; stay
119	 *                         connected and just wait.
120	 *   GT_ERR_IO (EPIPE / ECONNRESET): the hub is gone; disconnect, report
121	 *                         GT_IPC_EV_DISCONNECT, and retry after the wait. */
122	static void drain(gt_ipc_client *client, uint64_t now_ms, unsigned *events)
123	{
124	    if (!try_connect(client, now_ms, events)) {
125	        return;
126	    }
127	    /* Invariant: ring[head] is the oldest frame the kernel hasn't taken. */
128	    while (client->count > 0) {
129	        gt_status result = client->ops->send(client->ctx, client->ring[client->head], GT_MSG_SIZE);
130	        if (result == GT_ERR_FULL) {
131	            return;
132	        }
133	        if (result != GT_OK) {
134	            client->ops->disconnect(client->ctx);
135	            client->connected = 0;
136	            *events |= GT_IPC_EV_DISCONNECT;
137	            schedule_retry(client, now_ms);
138	            return;
139	        }
140	        client->head = (client->head + 1) % GT_IPC_RING_SLOTS;
141	        client->count--;
142	        client->stats.queued = (uint32_t)client->count;
143	        client->stats.sent++;
144	    }
145	}
146	
147	/* Queue the GAP message for the run of refused readings, and end the run.
148	 * Only called with at least 2 free slots, so the push can't fail and the
149	 * reading that follows it fits too. The encode can't fail either: the
150	 * sensor_id came from a reading that already encoded. */
151	static void push_gap(gt_ipc_client *client)
152	{
153	    gt_msg gap = {
154	        .type = GT_MSG_GAP, .sensor_id = client->gap_sensor_id,
155	        .counter = client->gap_first_counter, .seq = 0, .value = client->gap_count,
156	    };
157	    uint8_t frame[GT_MSG_SIZE];
158	    if (gt_msg_encode(&gap, frame) == GT_OK) {
159	        ring_push(client, frame);
160	    }
161	    client->gap_pending = 0;
162	}
163	
164	/* Put one reading's frame in the ring, or refuse it into the current gap.
165	 * A reading is refused when the ring is full, and also while a gap is
166	 * pending but fewer than 2 slots are free: the GAP must go in just before
167	 * the next accepted reading, so the hub sees old data, then the GAP, then
168	 * new data. The first refusal of a run starts the gap (its sensor, its
169	 * counter) and reports GT_IPC_EV_OVERFLOW; later ones only add to the
170	 * count. Every refusal is counted in stats.refused. */
171	static gt_status enqueue_reading(gt_ipc_client *client, const gt_msg *message,
172	                                 const uint8_t frame[GT_MSG_SIZE], unsigned *events)
173	{
174	    if (client->gap_pending && GT_IPC_RING_SLOTS - client->count >= 2) {
175	        push_gap(client);
176	    }
177	    /* With no gap pending, try the push; with one still pending, refuse. */
178	    if (!client->gap_pending && ring_push(client, frame) == GT_OK) {
179	        return GT_OK;
180	    }
181	    if (!client->gap_pending) {
182	        client->gap_pending = 1;
183	        client->gap_sensor_id = message->sensor_id;
184	        client->gap_first_counter = message->counter;
185	        client->gap_count = 0;
186	        *events |= GT_IPC_EV_OVERFLOW;
187	    }
188	    client->gap_count++;
189	    client->stats.refused++;
190	    return GT_ERR_FULL;
191	}
192	
193	/* Set up a client over any socket ops; no connect yet (the first send or
194	 * pump tries straight away, because next_attempt_ms starts at 0).
195	 * calloc is malloc that also zeroes the memory, so every counter, flag and
196	 * ring slot starts at 0 without setting each one. Once ops is known the
197	 * client owns ctx, so a failed allocation destroys it before returning
198	 * NULL; with NULL ops there is no destroy to call and the caller keeps ctx. */
199	gt_ipc_client *gt_ipc_client_open_ops(const gt_sock_ops *ops, void *ctx)
200	{
201	    if (ops == NULL) {
202	        return NULL;
203	    }
204	    gt_ipc_client *client = calloc(1, sizeof *client);
205	    if (client == NULL) {
206	        ops->destroy(ctx);
207	        return NULL;
208	    }
209	    client->ops = ops;
210	    client->ctx = ctx;
211	    client->backoff_ms = GT_IPC_BACKOFF_MIN_MS;
212	    return client;
213	}
214	
215	/* The real client: the Linux socket ops for `sock_path` (ipc_sock.c) under
216	 * gt_ipc_client_open_ops. Neither step connects. A bad path fails in
217	 * gt_ipc_sock_linux before any ctx exists, so there is nothing to free;
218	 * after that, open_ops owns the ctx and destroys it itself if it fails. */
219	gt_ipc_client *gt_ipc_client_open(const char *sock_path)
220	{
221	    const gt_sock_ops *ops = NULL;
222	    void *ctx = NULL;
223	    if (gt_ipc_sock_linux(sock_path, &ops, &ctx) != GT_OK) {
224	        return NULL;
225	    }
226	    return gt_ipc_client_open_ops(ops, ctx);
227	}
228	
229	/* Hand the ctx back to the socket layer exactly once (destroy also closes
230	 * any open connection), then free the client. Nothing more is sent, so
231	 * frames still in the ring are dropped. NULL is a no-op, like free(NULL). */
232	void gt_ipc_client_close(gt_ipc_client *client)
233	{
234	    if (client == NULL) {
235	        return;
236	    }
237	    client->ops->destroy(client->ctx);
238	    free(client);
239	}
240	
241	/* Encode `message`, queue it behind anything already waiting, and send
242	 * what the socket will take. The message is encoded first, so a bad one is
243	 * refused (GT_ERR_INVAL) before it takes a slot or causes a connect. The
244	 * ring is drained before the push as well as after: getting older frames
245	 * out first can free the slot this reading needs. */
246	gt_status gt_ipc_client_send(gt_ipc_client *client, const gt_msg *message,
247	                             uint64_t now_ms, unsigned *events_out)
248	{
249	    if (events_out != NULL) {
250	        *events_out = 0;
251	    }
252	    if (client == NULL || message == NULL) {
253	        return GT_ERR_INVAL;
254	    }
255	
256	    uint8_t frame[GT_MSG_SIZE];
257	    if (gt_msg_encode(message, frame) != GT_OK) {
258	        return GT_ERR_INVAL;
259	    }
260	    unsigned events = 0;
261	    drain(client, now_ms, &events);
262	    gt_status pushed = enqueue_reading(client, message, frame, &events);
263	    drain(client, now_ms, &events);
264	    if (events_out != NULL) {
265	        *events_out = events;
266	    }
267	    return pushed;
268	}
269	
270	/* The connect-and-drain half of send, with no new message: the sensor
271	 * loop calls this every tick, so a ring filled while the hub was down
272	 * still empties even when the sensor is offline and sends nothing. */
273	gt_status gt_ipc_client_pump(gt_ipc_client *client, uint64_t now_ms, unsigned *events_out)
274	{
275	    if (events_out != NULL) {
276	        *events_out = 0;
277	    }
278	    if (client == NULL) {
279	        return GT_ERR_INVAL;
280	    }
281	    unsigned events = 0;
282	    drain(client, now_ms, &events);
283	    if (events_out != NULL) {
284	        *events_out = events;
285	    }
286	    return GT_OK;
287	}
288	
289	/* Copy the counters out. `*stats_out = client->stats` is a struct
290	 * assignment: C copies every field of the struct in one statement, so the
291	 * caller gets a snapshot it can't use to change the client. */
292	gt_status gt_ipc_client_stats(const gt_ipc_client *client, gt_ipc_stats *stats_out)
293	{
294	    if (client == NULL || stats_out == NULL) {
295	        return GT_ERR_INVAL;
296	    }
297	    *stats_out = client->stats;
298	    return GT_OK;
299	}
