1	/* Unit tests for losing and regaining the hub in the IPC client
2	 * (src/ipc_client.c): connect retries in gt_ipc_client_send and
3	 * gt_ipc_client_pump.
4	 *
5	 * Purpose: prove the DESIGN.md Sensor -> hub row's reconnect rule. Retries
6	 * wait 100, 200, 400, 800 and 1600 ms, then 2000 ms each, never earlier,
7	 * and a successful connect resets the wait to 100 ms. A lost hub is
8	 * reported once (GT_IPC_EV_DISCONNECT) and regaining it once
9	 * (GT_IPC_EV_RECONNECT). No reading is dropped meanwhile: the buffered
10	 * frames go out oldest first once the hub is back. Time is passed in as
11	 * now_ms, so these run with no clock and no sleeps, against
12	 * tests/fake_sock.h. Run under make test / asan / memcheck. Implements
13	 * ICR-01 through ICR-08. Sending to a reachable hub is test_ipc_send.c; a
14	 * full ring is test_ipc_overflow.c.
15	 *
16	 * What these tests cannot prove: that a real kernel reports a dead hub as
17	 * ENOENT / ECONNREFUSED / EPIPE. That's test_ipc_loopback.c. */
18	#include <stdint.h>
19	#include <string.h>
20	
21	#include "check.h"
22	#include "fake_sock.h"
23	#include "ipc.h"
24	#include "ipc_sock.h"
25	
26	/* Reset `fake` and open a client on it. */
27	static gt_ipc_client *open_on(fake_sock *fake)
28	{
29	    return gt_ipc_client_open_ops(fake_sock_ops(fake), fake);
30	}
31	
32	/* A light DATA reading; seq is 0 because only the hub stamps it. */
33	static gt_msg light_reading(uint32_t counter, uint32_t raw)
34	{
35	    gt_msg message = {
36	        .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_LIGHT,
37	        .counter = counter, .seq = 0, .value = raw,
38	    };
39	    return message;
40	}
41	
42	/* Whether the fake's sent frame number `sent_index` is exactly
43	 * gt_msg_encode(message). */
44	static int sent_frame_is(const fake_sock *fake, size_t sent_index, const gt_msg *message)
45	{
46	    uint8_t expected[GT_MSG_SIZE];
47	    if (gt_msg_encode(message, expected) != GT_OK || sent_index >= fake->n_sent) {
48	        return 0;
49	    }
50	    return memcmp(fake->sent[sent_index], expected, GT_MSG_SIZE) == 0;
51	}
52	
53	/* ---- ICR-01: failed connect buffers, no event ----
54	 * The hub isn't up yet. The reading is still accepted (GT_OK: buffered),
55	 * nothing is sent, and there's no event: never having connected is not a
56	 * lost connection. */
57	static void test_icr01_failed_connect_buffers(void)
58	{
59	    fake_sock fake;
60	    gt_ipc_client *client = open_on(&fake);
61	    fake.fail_connects = 1;
62	    gt_msg reading = light_reading(1, 100);
63	    unsigned events = 0xFFu;
64	
65	    CHECK_EQ(gt_ipc_client_send(client, &reading, 0, &events), GT_OK);
66	    CHECK_EQ(fake.connect_calls, 1);
67	    CHECK_EQ(fake.send_calls, 0);
68	    CHECK_EQ(events, 0);
69	
70	    gt_ipc_client_close(client);
71	}
72	
73	/* One pump at `now_ms`, after which the fake should have seen
74	 * `connect_calls` attempts in total. */
75	typedef struct {
76	    uint64_t now_ms;
77	    int      connect_calls;
78	} attempt_check;
79	
80	/* Pump at each row's time and check the running attempt count. */

