    CHECK_EQ(gt_hub_sender_pump(sender, 1000, &events), GT_OK);
    CHECK_EQ(gt_hub_sender_pump(sender, 1000 + GT_HUB_RESUME_WAIT_MS - 1, &events), GT_OK);
    CHECK_EQ(events, 0);
