1	/* Loopback tests for the storage rx loop over a real socket
2	 * (src/storage_server.c): gt_storage_serve.
3	 *
4	 * Purpose: prove the loop does over a real AF_UNIX SOCK_SEQPACKET socket
5	 * what gt_storage_rx decides on paper. A hub that connects is sent
6	 * seq_resume at once. Its frames are stored, and a duplicate is refused
7	 * while the connection stays open. A malformed frame closes the
8	 * connection, so the hub sees end-of-file and reconnects. A newer hub
9	 * connection replaces an older one. On stop, frames already sent are
10	 * still taken before it returns.
11	 *
12	 * The loop runs in a second thread (pthread_create starts a function on
13	 * its own thread; pthread_join waits for it to finish), over storage on
14	 * tests/fake_file.h: only the socket is real. Each test uses its own
15	 * mkdtemp directory under /tmp and removes it after. Waits are bounded by
16	 * poll() timeouts, so a broken loop is a FAIL line, not a hang. Run under
17	 * make test / asan / memcheck. Implements SSV-01 through SSV-07.
18	 *
19	 * Note: macOS does not support SOCK_SEQPACKET for AF_UNIX, so these run on
20	 * Linux (WSL and the Pi) only, like test_listen_bind.c. */
21	#include <poll.h>
22	#include <pthread.h>
23	#include <stdio.h>
24	#include <stdlib.h>
25	#include <string.h>
26	#include <sys/socket.h>
27	#include <sys/un.h>
28	#include <unistd.h>
29	
30	#include "check.h"
31	#include "fake_file.h"
32	#include "listen_sock.h"
33	#include "log_record.h"
34	#include "storage.h"
35	#include "storage_server.h"
36	
37	#define TODAY_US      ((uint64_t)(1792972800u + 3600u) * 1000000u)   /* 2026-10-26 01:00 UTC */
38	#define TODAY_NAME    "log-20261026.bin"
39	#define TEST_CAPACITY 16
40	#define WAIT_MS       2000   /* longest any test waits for the loop */
41	
42	static fake_fs fs;   /* static: a fake_fs is about 70 KB (see fake_file.h) */
43	
44	/* Event names the loop logged, in order. Written only by the loop's
45	 * thread, read only after it has been joined. */
46	typedef struct {
47	    size_t count;
48	    char   events[32][32];
49	} event_book;
50	
51	static event_book book;
52	
53	static void record_log(void *log_ctx, gt_log_level level, const char *event, const char *fields)
54	{
55	    event_book *records = log_ctx;
56	    (void)level;
57	    (void)fields;
58	    if (records->count < 32) {
59	        strncpy(records->events[records->count], event, sizeof records->events[0] - 1);
60	        records->count++;
61	    }
62	}
63	
64	/* How many logged events were called `event`. */
65	static size_t logged(const char *event)
66	{
67	    size_t matches = 0;
68	    for (size_t log_index = 0; log_index < book.count; log_index++) {
69	        if (strcmp(book.events[log_index], event) == 0) {
70	            matches++;
71	        }
72	    }
73	    return matches;
74	}
75	
76	/* One test's server: the directory, socket path, lock, listener, stop
77	 * pipe (stop_pipe[1] is written to stop the loop), storage, the loop's
78	 * thread and what it returned. */
79	typedef struct {
80	    char        dir[32];
81	    char        path[64];
82	    int         lock_fd;
83	    int         listen_fd;
84	    int         stop_pipe[2];
85	    gt_storage *storage;
86	    pthread_t   thread;
87	    gt_status   result;
88	} server;
89	
90	/* The thread's body: run the loop and keep what it returned. */
91	static void *serve_thread(void *arg)
92	{
93	    server *running = arg;
94	    running->result = gt_storage_serve(running->storage, running->listen_fd,
95	                                       running->stop_pipe[0], record_log, &book);
96	    return NULL;
97	}
98	
99	/* Make storage (over the fake, with records 1 .. last_on_disk already in
100	 * today's segment), a listener in a fresh directory, and start the loop.
101	 * Returns 1 on success. */
102	static int start_server(server *running, uint32_t last_on_disk)
103	{
104	    memset(running, 0, sizeof *running);
105	    memset(&book, 0, sizeof book);
106	    const gt_file_ops *ops = fake_fs_ops(&fs);
107	    if (last_on_disk > 0) {
108	        uint8_t segment[GT_SEG_HEADER_SZ + 8 * GT_REC_SIZE];
109	        const gt_seg_header header = { .created_at_us = 1000 };
110	        CHECK_EQ(gt_seg_header_encode(&header, segment), GT_OK);
111	        /* invariant: records 1 .. seq - 1 are encoded after the header */
112	        for (uint32_t seq = 1; seq <= last_on_disk; seq++) {
113	            const gt_record record = { .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT,
114	                                       .seq = seq, .timestamp_us = seq, .value = seq };
115	            CHECK_EQ(gt_record_encode(&record, &segment[GT_SEG_HEADER_SZ
116	                                                        + (seq - 1) * GT_REC_SIZE]), GT_OK);
117	        }
118	        CHECK_EQ(fake_fs_put(&fs, TODAY_NAME, segment,
119	                             GT_SEG_HEADER_SZ + last_on_disk * GT_REC_SIZE), GT_OK);
120	    }
121	    gt_storage_open_args args = { .ops = ops, .ctx = &fs, .now_us = TODAY_US,
122	                                  .pending_capacity = TEST_CAPACITY };
123	    if (gt_storage_open_ops(&args, &running->storage, NULL) != GT_OK) {
124	        return 0;
125	    }
126	    strcpy(running->dir, "/tmp/gt-ssv-XXXXXX");
127	    if (mkdtemp(running->dir) == NULL) {
128	        return 0;
129	    }
130	    snprintf(running->path, sizeof running->path, "%s/storage.sock", running->dir);
131	    int already_running = 0;
132	    if (gt_listen_lock(running->path, &running->lock_fd, &already_running) != GT_OK
133	        || gt_listen_bind(running->path, 4, &running->listen_fd) != GT_OK
134	        || pipe(running->stop_pipe) != 0) {
135	        return 0;
136	    }
137	    return pthread_create(&running->thread, NULL, serve_thread, running) == 0;
138	}
139	
140	/* Stop the loop (one byte down the stop pipe), wait for its thread, and
141	 * check it returned GT_OK. Storage stays open for the test to inspect. */
142	static void stop_server(server *running)
143	{
144	    const char stop_byte = 's';
145	    CHECK(write(running->stop_pipe[1], &stop_byte, 1) == 1);
146	    pthread_join(running->thread, NULL);
147	    CHECK_EQ(running->result, GT_OK);
148	}
149	
150	/* Free everything start_server made. */
151	static void remove_server(server *running)
152	{
153	    gt_storage_close(running->storage);
154	    close(running->stop_pipe[0]);
155	    close(running->stop_pipe[1]);
156	    gt_listen_release(running->path, running->listen_fd, running->lock_fd);
157	    char lock_path[80];
158	    snprintf(lock_path, sizeof lock_path, "%s.lock", running->path);
159	    unlink(lock_path);
160	    rmdir(running->dir);
161	}
162	
163	/* Connect a client (the hub) to the server. Returns the fd, or -1. */
164	static int connect_hub(const server *running)
165	{
166	    struct sockaddr_un addr;
167	    memset(&addr, 0, sizeof addr);
168	    addr.sun_family = AF_UNIX;
169	    strncpy(addr.sun_path, running->path, sizeof addr.sun_path - 1);
170	    int hub_fd = socket(AF_UNIX, SOCK_SEQPACKET, 0);
171	    if (hub_fd >= 0 && connect(hub_fd, (const struct sockaddr *)&addr, sizeof addr) != 0) {
172	        close(hub_fd);
173	        hub_fd = -1;
174	    }
175	    return hub_fd;
176	}
177	
178	/* Wait up to WAIT_MS for something to read on hub_fd, then recv it into
179	 * buf. Returns recv's result, or -2 if nothing came in time. */
180	static long recv_waiting(int hub_fd, uint8_t *buf, size_t buf_size)
181	{
182	    struct pollfd wait_for = { .fd = hub_fd, .events = POLLIN, .revents = 0 };
183	    if (poll(&wait_for, 1, WAIT_MS) != 1) {
184	        return -2;
185	    }
186	    return (long)recv(hub_fd, buf, buf_size, 0);
187	}
188	
189	/* Read the seq_resume reply a new connection is sent, and decode it. */
190	static int read_resume(int hub_fd, gt_resume *resume)
191	{
192	    uint8_t reply[GT_RESUME_SIZE + 1];
193	    return recv_waiting(hub_fd, reply, sizeof reply) == GT_RESUME_SIZE
194	           && gt_resume_decode(reply, resume) == GT_OK;
195	}
196	
197	/* Send a light DATA record with `seq`, as the hub would. */
198	static void send_record(int hub_fd, uint32_t seq)
199	{
200	    const gt_record record = { .type = GT_REC_DATA, .sensor_id = GT_SENSOR_LIGHT,
201	                               .seq = seq, .timestamp_us = 1000 + seq, .value = seq };
202	    uint8_t wire[GT_REC_SIZE];
203	    CHECK_EQ(gt_record_encode(&record, wire), GT_OK);
204	    CHECK(send(hub_fd, wire, sizeof wire, 0) == (ssize_t)sizeof wire);
205	}
206	
207	/* The newest accepted seq and the pending count. */
208	static gt_storage_stats read_stats(const server *running)
209	{
210	    gt_storage_stats stats;
211	    CHECK_EQ(gt_storage_read_stats(running->storage, &stats), GT_OK);
212	    return stats;
213	}
214	
215	/* ---- SSV-01: a new hub is sent seq_resume ----
216	 * Empty log: has_last 0. Log ending at 5: seq 5. */
217	static void test_ssv01_resume_on_connect(void)
218	{
219	    for (uint32_t last_on_disk = 0; last_on_disk <= 5; last_on_disk += 5) {
220	        server running;
