    CHECK_EQ(stored.sensor_id, GT_SENSOR_LIGHT);
    CHECK_EQ(stored.value, 1234);
    CHECK_EQ(stored.seq, 0);
    CHECK_EQ(logged("sensor_connected"), 1);
    CHECK_EQ(logged("seq_resume"), 1);
