1	/* storage_main: the storage process (DESIGN.md Mechanism D).
2	 *
3	 * Purpose: wire the tested pieces together into one long-running process.
4	 * Every decision lives in the library (storage*.c, storage_server.c,
5	 * storage_flusher.c, listen_sock.c); this file only orders the start-up,
6	 * owns the threads and signals, and prints log lines. Start-up order:
7	 *   1. Take the one-listener lock for the socket path FIRST. It guards the
8	 *      log as well as the socket: two storage processes recovering and
9	 *      appending to one segment would corrupt it. A second copy exits
10	 *      with "already running" and touches nothing.
11	 *   2. Open storage. Recovery runs here, before any data can arrive
12	 *      (DESIGN.md "recovery runs before storage.sock accepts any data").
13	 *      On an empty log with an unsynced clock it first waits up to 120 s
14	 *      for the clock, so the first segment isn't named 1970 (PF-20).
15	 *   3. Bind storage.sock: only now can the hub connect.
16	 *   4. Start the flush thread, then run the rx loop on this thread.
17	 * On SIGTERM or SIGINT the handler only sets a flag and writes one byte to
18	 * a pipe (all a signal handler may safely do); the rx loop wakes, takes the
19	 * frames already sent and returns; the flush thread is joined; then a
20	 * clean shutdown (final flush + marker), close, and the socket and lock
21	 * are released.
22	 *
23	 * After the rx loop returns, gt_storage_wake ends the flush thread's wait
24	 * so it sees the stop at once.
25	 *
26	 * -n N and -t T_SECONDS set when a flush is due (default 64 records and
27	 * 60 s), so DESIGN.md's (N, T) experiment runs on one build (PF-11);
28	 * storage_start logs them as batch_n and batch_t_s.
29	 *
30	 * Log lines go to stderr in gt_log_format's format, component "storage"
31	 * (the shared sink, PF-18). The heartbeat to sup.sock arrives with
32	 * Mechanism E.
33	 *
34	 * Usage: storage_main [-n N] [-t T_SECONDS] /var/lib/plantpi /run/plantpi/storage.sock */
35	#define _DEFAULT_SOURCE   /* adjtimex() in <sys/timex.h> is a Linux extension */
36	
37	#include <errno.h>
38	#include <pthread.h>
39	#include <signal.h>
40	#include <stdatomic.h>
41	#include <stdio.h>
42	#include <stdlib.h>
43	#include <string.h>
44	#include <sys/stat.h>
45	#include <time.h>
46	#include <unistd.h>
47	#ifdef __linux__
48	#include <sys/timex.h>
49	#endif
50	
51	#include "gt_log.h"
52	#include "listen_sock.h"
53	#include "storage.h"
54	#include "storage_pending.h"
55	#include "storage_server.h"
56	
57	#define LISTEN_BACKLOG 4
58	
59	/* 2026-10-01 00:00 UTC: no correct clock can read earlier than the start
60	 * of this project, so an earlier reading means the Pi booted with no
61	 * network time and no RTC (DESIGN.md: "a timestamp earlier than the build
62	 * date"). */
63	#define EARLIEST_VALID_S 1790812800
64	
65	/* How long an empty log waits for the clock before the first segment is
66	 * named (wait_for_clock_if_empty, PF-20). */
67	#define CLOCK_WAIT_MAX_S 120
68	
69	/* The largest -t: a day. Longer would only hold records in memory past
70	 * DESIGN.md's commit-latency target for no gain. */
71	#define BATCH_AGE_MAX_S 86400
72	
73	/* Set by the signal handler, read by both threads. */
74	static atomic_int stop_requested;
75	/* The write end of the stop pipe, for the signal handler. */
76	static int stop_write_fd = -1;
77	
78	/* Wall-clock time in us since the epoch, for log lines and the segment
79	 * name. */
80	static uint64_t wall_us(void)
81	{
82	    struct timespec now;
83	    clock_gettime(CLOCK_REALTIME, &now);
84	    return (uint64_t)now.tv_sec * 1000000u + (uint64_t)now.tv_nsec / 1000u;
85	}
86	
87	/* Monotonic time in us, for timing commits (gt_storage_set_clock, PF-08).
88	 * CLOCK_MONOTONIC never jumps when the wall clock is set, so a duration is
89	 * never negative or inflated by an NTP step. */
90	static uint64_t monotonic_us(void)
91	{
92	    struct timespec now;
93	    clock_gettime(CLOCK_MONOTONIC, &now);
94	    return (uint64_t)now.tv_sec * 1000000u + (uint64_t)now.tv_nsec / 1000u;
95	}
96	
97	/* The log callback: one gt_log_format line on stderr. */
98	static void log_line(void *log_ctx, gt_log_level level, const char *event, const char *fields)
99	{
100	    (void)log_ctx;
101	    char line[GT_LOG_LINE_MAX];
102	    /* Designated initializers: each field is set by name. */
103	    gt_log_entry entry = { .timestamp_us = wall_us(), .level = level, .component = "storage",
104	                           .event = event, .fields = fields };
105	    if (gt_log_format(line, sizeof line, &entry) == GT_OK) {
106	        fprintf(stderr, "%s\n", line);
107	    }
108	}
109	
110	/* 1 if the wall clock can be trusted for rollover and retention: the
111	 * kernel says NTP has synced it (adjtimex returns TIME_ERROR while it
112	 * hasn't), and it is not earlier than this project. adjtimex is Linux
113	 * only; elsewhere only the date check is made. */
114	static int clock_synced(void)
115	{
116	    if (wall_us() / 1000000u < EARLIEST_VALID_S) {
117	        return 0;
118	    }
119	#ifdef __linux__
120	    struct timex clock_state;
121	    memset(&clock_state, 0, sizeof clock_state);   /* modes = 0: only read */
122	    int state = adjtimex(&clock_state);
123	    if (state == -1 || state == TIME_ERROR) {
124	        return 0;
125	    }
126	#endif
127	    return 1;
128	}
129	
130	/* On an empty log, wait up to CLOCK_WAIT_MAX_S for the clock before open
131	 * names the first segment, so a Pi that booted without network time
132	 * doesn't start log-19700101.bin (PF-20). A log that already holds a
133	 * segment needs no wait: open reuses the newest, and rollover is skipped
134	 * while the clock is unsynced. The hub's 1024-record queue (about 17 min
135	 * at 1 Hz) holds readings meanwhile. If the clock is still unsynced at the
136	 * end, open goes ahead with the time it has (logged at WARN). Signals are
137	 * not installed yet, so a SIGTERM here simply ends the process. */
138	static void wait_for_clock_if_empty(const char *log_dir)
139	{
140	    int empty = 0;
141	    if (gt_storage_log_empty(log_dir, &empty) != GT_OK || !empty || clock_synced()) {
142	        return;
143	    }
144	    char fields[48];
145	    snprintf(fields, sizeof fields, "max_s=%d", CLOCK_WAIT_MAX_S);
146	    log_line(NULL, GT_LOG_WARN, "clock_wait", fields);
147	    const struct timespec one_second = { 1, 0 };
148	    int waited_s = 0;
149	    /* invariant: the clock was unsynced at every one of the waited_s checks */
150	    while (waited_s < CLOCK_WAIT_MAX_S && !clock_synced()) {
151	        nanosleep(&one_second, NULL);
152	        waited_s++;
153	    }
154	    int synced = clock_synced();
155	    snprintf(fields, sizeof fields, "waited_s=%d synced=%d", waited_s, synced);
156	    log_line(NULL, synced ? GT_LOG_INFO : GT_LOG_WARN, "clock_wait_done", fields);
157	}
158	
159	/* Parse a whole decimal number from 1 to max_value. Returns 1 on success;
160	 * *value_out is untouched on failure. */
161	static int parse_bounded(const char *text, unsigned long max_value, unsigned long *value_out)
162	{
163	    if (text[0] < '0' || text[0] > '9') {
164	        return 0;   /* empty, or a sign/space strtoul would accept */
165	    }
166	    char *end = NULL;
167	    errno = 0;
168	    unsigned long value = strtoul(text, &end, 10);
169	    if (errno != 0 || *end != '\0' || value == 0 || value > max_value) {
170	        return 0;
171	    }
172	    *value_out = value;
173	    return 1;
174	}
175	
176	/* Read the optional "-n N" and "-t T_SECONDS" pairs at the front of argv,
177	 * in either order, into *batch_out and *age_s_out (left at their defaults
178	 * if not given). N runs from 1 to the pending buffer's size, T from 1 s to
179	 * a day. *arg_base_out is the index of the first argument after them.
180	 * Returns 1 on success, 0 for a bad or repeated option. */
181	static int parse_batch_options(int argc, char **argv, unsigned long *batch_out,
182	                               unsigned long *age_s_out, int *arg_base_out)
183	{
184	    int seen_batch = 0, seen_age = 0;
185	    int arg_index = 1;
186	    /* invariant: argv[1 .. arg_index - 1] are whole, valid option pairs */
187	    while (arg_index + 1 < argc && argv[arg_index][0] == '-') {
188	        const char *flag = argv[arg_index];
189	        int ok = 0;   /* stays 0 for an unknown or repeated option */
190	        if (strcmp(flag, "-n") == 0 && !seen_batch) {
191	            seen_batch = parse_bounded(argv[arg_index + 1], GT_PENDING_MAX_RECORDS, batch_out);
192	            ok = seen_batch;
193	        } else if (strcmp(flag, "-t") == 0 && !seen_age) {
194	            seen_age = parse_bounded(argv[arg_index + 1], BATCH_AGE_MAX_S, age_s_out);
195	            ok = seen_age;
196	        }
197	        if (!ok) {
198	            return 0;
199	        }
200	        arg_index += 2;
201	    }
202	    *arg_base_out = arg_index;
203	    return 1;
204	}
205	
206	/* SIGTERM / SIGINT: set the flag and wake the rx loop's poll(). errno is
207	 * saved and restored, because write() may change it under the code the
208	 * signal interrupted. */
209	static void on_stop_signal(int signum)
210	{
211	    (void)signum;
212	    int saved_errno = errno;
213	    const char stop_byte = 's';
214	    atomic_store(&stop_requested, 1);
215	    if (stop_write_fd >= 0 && write(stop_write_fd, &stop_byte, 1) < 0) {
216	        /* nothing more a signal handler can do */
217	    }
218	    errno = saved_errno;
219	}
220	
221	/* The flush thread's start function: pthread_create calls it with the
222	 * gt_flusher as `arg`. */
223	static void *flusher_thread(void *arg)
224	{
225	    gt_flusher_run(arg, &stop_requested, clock_synced);
226	    return NULL;
227	}
228	
229	/* Log what recovery did to one segment: segment_corrupt if it was renamed
230	 * to .corrupt, otherwise recovery_event with what was cut (WARN if
231	 * anything was). */
232	static void log_recovery(const char *name, const gt_recover_report *report)
233	{
234	    char fields[160];
235	    if (report->outcome == GT_RECOVER_RENAMED) {
236	        snprintf(fields, sizeof fields, "segment=%s bytes=%llu", name,
237	                 (unsigned long long)report->bytes_removed);
238	        log_line(NULL, GT_LOG_ERROR, "segment_corrupt", fields);
239	    } else {
240	        snprintf(fields, sizeof fields, "segment=%s bytes_removed=%llu records_removed=%lu",
241	                 name, (unsigned long long)report->bytes_removed,
242	                 (unsigned long)report->records_removed);
243	        log_line(NULL, report->records_removed > 0 ? GT_LOG_WARN : GT_LOG_INFO,
244	                 "recovery_event", fields);
245	    }
246	}
247	
248	/* Log what open found: whether the last run ended cleanly, and what
249	 * recovery did to the newest segment (DESIGN.md: unclean_shutdown,
250	 * recovery_event, segment_corrupt). storage_start also carries N and T,
251	 * so a run of the (N, T) experiment says which point it was (PF-11). */
252	static void log_open_info(const gt_storage_open_info *info, unsigned long batch_records,
253	                          unsigned long batch_age_s)
254	{
255	    char fields[160];
256	    if (info->unclean_shutdown) {
257	        log_line(NULL, GT_LOG_WARN, "unclean_shutdown", NULL);
258	    }
259	    if (info->recovered) {
260	        log_recovery(info->recovered_name, &info->recovery);
261	    }
262	    /* Older segments the walk back for the last seq changed (PF-14). */
263	    for (size_t older_index = 0; older_index < info->older_count; older_index++) {
264	        log_recovery(info->older[older_index].name, &info->older[older_index].report);
265	    }
266	    if (info->older_unlisted > 0) {
267	        snprintf(fields, sizeof fields, "segments=%lu", (unsigned long)info->older_unlisted);
268	        log_line(NULL, GT_LOG_WARN, "recovery_unlisted", fields);
269	    }
270	    if (info->has_last) {
271	        snprintf(fields, sizeof fields, "segment=%s created=%d last_seq=%lu batch_n=%lu batch_t_s=%lu",
272	                 info->active_name, info->created, (unsigned long)info->last_seq,
273	                 batch_records, batch_age_s);
274	    } else {
275	        snprintf(fields, sizeof fields, "segment=%s created=%d last_seq=none batch_n=%lu batch_t_s=%lu",
276	                 info->active_name, info->created, batch_records, batch_age_s);
277	    }
278	    log_line(NULL, GT_LOG_INFO, "storage_start", fields);
279	}
280	
281	/* Install the stop handler for SIGTERM and SIGINT, and ignore SIGPIPE (a
282	 * second guard, besides MSG_NOSIGNAL, against a dead hub killing
283	 * storage). `struct sigaction` describes what to do on a signal; no
284	 * SA_RESTART, so a blocked call returns EINTR and the loops can check
285	 * the flag. */
286	static void install_signals(void)
287	{
288	    struct sigaction action;
289	    memset(&action, 0, sizeof action);
290	    action.sa_handler = on_stop_signal;
291	    sigemptyset(&action.sa_mask);
292	    sigaction(SIGTERM, &action, NULL);
293	    sigaction(SIGINT, &action, NULL);
294	    signal(SIGPIPE, SIG_IGN);
295	}
296	
297	/* Start the flush thread with SIGTERM and SIGINT blocked in it, so the
298	 * signals are always handled on this (the rx) thread: a new thread
299	 * inherits the signal mask of the one that creates it, so the mask is
300	 * set, the thread made, and the mask put back. Returns 1 on success. */
301	static int start_flusher(pthread_t *thread, gt_flusher *flusher)
302	{
303	    sigset_t stop_signals, previous;
304	    sigemptyset(&stop_signals);
305	    sigaddset(&stop_signals, SIGTERM);
306	    sigaddset(&stop_signals, SIGINT);
307	    pthread_sigmask(SIG_BLOCK, &stop_signals, &previous);
308	    int created = pthread_create(thread, NULL, flusher_thread, flusher) == 0;
309	    pthread_sigmask(SIG_SETMASK, &previous, NULL);
310	    return created;
311	}
312	
313	/* Say why the one-listener lock wasn't taken: another storage_main holds
314	 * it, or the lock file itself failed (errno says how). */
315	static void report_lock_error(const char *sock_path, int already_running)
316	{
317	    if (already_running) {
318	        fprintf(stderr, "storage_main: already running on %s (%s.lock is locked)\n",
319	                sock_path, sock_path);
320	        return;
321	    }
322	    fprintf(stderr, "storage_main: lock %s.lock: %s\n", sock_path, strerror(errno));
323	}
324	
325	/* Start-up step 2: make the log directory if it isn't there yet (a fresh
326	 * install), open storage (recovery runs here), log what open found, and
327	 * set the clock and (N, T) before the flush thread starts. N and T were
328	 * range-checked by the caller, so set_batch can't fail (PF-11). Returns
329	 * NULL on failure, already reported. */
330	static gt_storage *open_storage(const char *log_dir, unsigned long batch_records,
331	                                unsigned long batch_age_s)
332	{
333	    if (mkdir(log_dir, 0755) != 0 && errno != EEXIST) {
334	        fprintf(stderr, "storage_main: %s: %s\n", log_dir, strerror(errno));
335	        return NULL;
336	    }
337	    wait_for_clock_if_empty(log_dir);
338	    gt_storage *storage = NULL;
339	    gt_storage_open_info info;
340	    gt_status status = gt_storage_open(log_dir, wall_us(), &storage, &info);
341	    if (status != GT_OK) {
342	        char fields[48];
343	        snprintf(fields, sizeof fields, "status=%d", (int)status);
344	        log_line(NULL, GT_LOG_ERROR, "storage_open_error", fields);
345	        return NULL;
346	    }
347	    log_open_info(&info, batch_records, batch_age_s);
348	    gt_storage_set_clock(storage, monotonic_us);
349	    gt_storage_set_batch(storage, (size_t)batch_records, (unsigned)batch_age_s);
350	    return storage;
351	}
352	
353	/* The whole life of the process after the arguments are read: start-up
354	 * steps 1-4, the rx loop, then shutdown. Returns the exit code: 0 for a
355	 * clean stop, 1 for any failure. */
356	static int run_storage(const char *log_dir, const char *sock_path,
357	                       unsigned long batch_records, unsigned long batch_age_s)
358	{
359	    /* 1. The lock, before anything touches the log. */
360	    int lock_fd = -1, already_running = 0;
361	    if (gt_listen_lock(sock_path, &lock_fd, &already_running) != GT_OK) {
362	        report_lock_error(sock_path, already_running);
363	        return 1;
364	    }
365	
366	    /* 2. Open storage; recovery runs here. */
367	    gt_storage *storage = open_storage(log_dir, batch_records, batch_age_s);
368	    if (storage == NULL) {
369	        gt_listen_release(sock_path, -1, lock_fd);
370	        return 1;
371	    }
372	
373	    /* 3. Bind storage.sock, and make the stop pipe. */
374	    int listen_fd = -1;
375	    int stop_pipe[2] = { -1, -1 };
376	    if (gt_listen_bind(sock_path, LISTEN_BACKLOG, &listen_fd) != GT_OK || pipe(stop_pipe) != 0) {
377	        fprintf(stderr, "storage_main: %s: %s\n", sock_path, strerror(errno));
378	        gt_storage_shutdown(storage, NULL);
379	        gt_storage_close(storage);
380	        gt_listen_release(sock_path, listen_fd, lock_fd);
381	        return 1;
382	    }
383	    stop_write_fd = stop_pipe[1];
384	    install_signals();
385	
386	    /* 4. The flush thread, then the rx loop until a stop. */
387	    gt_flusher flusher;
388	    gt_flusher_init(&flusher, storage, 0, log_line, NULL);
389	    pthread_t flush_thread;
390	    int flusher_running = start_flusher(&flush_thread, &flusher);
391	    if (!flusher_running) {
392	        log_line(NULL, GT_LOG_ERROR, "flusher_start_error", NULL);
393	    }
394	    if (flusher_running
395	        && gt_storage_serve(storage, listen_fd, stop_pipe[0], log_line, NULL) != GT_OK) {
396	        log_line(NULL, GT_LOG_ERROR, "rx_loop_error", NULL);
397	    }
398	
399	    /* Shut down: stop and join the flush thread, then the final flush and
400	     * the marker, then release everything. */
401	    atomic_store(&stop_requested, 1);
402	    gt_storage_wake(storage);   /* the flush thread sees the stop at once (PF-11) */
403	    if (flusher_running) {
404	        pthread_join(flush_thread, NULL);
405	    }
406	    unsigned events = 0;
407	    gt_storage_stats stats;
408	    gt_storage_read_stats(storage, &stats);
409	    uint64_t commits_before = stats.commits;
410	    gt_status shutdown_status = gt_storage_shutdown(storage, &events);
411	    gt_storage_log_events(log_line, NULL, events);
412	    gt_storage_log_commit(log_line, NULL, storage, commits_before);   /* the final flush */
413	    gt_storage_read_stats(storage, &stats);
414	    /* The segment and last committed seq say where the log ended (PF-14),
415	     * matching storage_start's fields. The flush thread has been joined,
416	     * so reading the active segment's name is safe. */
417	    char last_seq[16] = "none";
418	    if (stats.has_last_committed) {
419	        snprintf(last_seq, sizeof last_seq, "%lu", (unsigned long)stats.last_committed_seq);
420	    }
421	    char segment[GT_FILE_NAME_MAX] = "none";
422	    gt_storage_active_segment(storage, segment);
423	    char fields[160];
424	    snprintf(fields, sizeof fields, "clean=%d segment=%s last_seq=%s committed=%llu refused=%llu",
425	             shutdown_status == GT_OK, segment, last_seq,
426	             (unsigned long long)stats.committed_records, (unsigned long long)stats.refused);
427	    log_line(NULL, shutdown_status == GT_OK ? GT_LOG_INFO : GT_LOG_ERROR, "storage_stop", fields);
428	
429	    gt_storage_close(storage);
430	    stop_write_fd = -1;
431	    close(stop_pipe[0]);
432	    close(stop_pipe[1]);
433	    gt_listen_release(sock_path, listen_fd, lock_fd);
434	    return shutdown_status == GT_OK && flusher_running ? 0 : 1;
435	}
436	
437	int main(int argc, char **argv)
438	{
439	    unsigned long batch_records = GT_BATCH_MAX_RECORDS;
440	    unsigned long batch_age_s = GT_BATCH_MAX_AGE_S;
441	    int arg_base = 1;
442	    if (!parse_batch_options(argc, argv, &batch_records, &batch_age_s, &arg_base)
443	        || argc - arg_base != 2) {
444	        fprintf(stderr,
445	                "usage: %s [-n N] [-t T_SECONDS] /var/lib/plantpi /run/plantpi/storage.sock\n"
446	                "  N: flush at N records, 1..%u (default %u)\n"
447	                "  T: flush once the oldest record is T s old, 1..%u (default %u)\n",
448	                argv[0], (unsigned)GT_PENDING_MAX_RECORDS, (unsigned)GT_BATCH_MAX_RECORDS,
449	                (unsigned)BATCH_AGE_MAX_S, (unsigned)GT_BATCH_MAX_AGE_S);
450	        return 2;
451	    }
452	    return run_storage(argv[arg_base], argv[arg_base + 1], batch_records, batch_age_s);
453	}
