/* Throwaway end-to-end feeder (not committed): stands in for the light
 * and soil processes. Light sends at 10 Hz and soil at 1 Hz, each through
 * its own real IPC client to hub.sock, for DURATION_S seconds; both are
 * pumped every 100 ms tick. Client events are printed as they happen;
 * the final line gives each sensor's counts.
 * Usage: sensor_feed HUB_SOCK DURATION_S */
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "ipc.h"

static uint64_t mono_ms(void)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (uint64_t)now.tv_sec * 1000u + (uint64_t)now.tv_nsec / 1000000u;
}

static void report(const char *sensor, unsigned events, uint64_t elapsed_ms)
{
    if (events & GT_IPC_EV_DISCONNECT) {
        printf("t=%.1f %s ipc_disconnect\n", elapsed_ms / 1000.0, sensor);
    }
    if (events & GT_IPC_EV_RECONNECT) {
        printf("t=%.1f %s ipc_reconnect\n", elapsed_ms / 1000.0, sensor);
    }
    if (events & GT_IPC_EV_OVERFLOW) {
        printf("t=%.1f %s ipc_overflow\n", elapsed_ms / 1000.0, sensor);
    }
}

int main(int argc, char **argv)
{
    if (argc != 3) {
        return 2;
    }
    setvbuf(stdout, NULL, _IOLBF, 0);
    gt_ipc_client *light = gt_ipc_client_open(argv[1]);
    gt_ipc_client *soil = gt_ipc_client_open(argv[1]);
    unsigned long ticks = strtoul(argv[2], NULL, 10) * 10u;
    uint64_t start_ms = mono_ms();
    uint32_t light_counter = 0, soil_counter = 0;
    for (unsigned long tick = 0; tick < ticks; tick++) {
        uint64_t now = mono_ms();
        unsigned events = 0;
        gt_msg reading = { .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_LIGHT,
                           .counter = light_counter++, .seq = 0, .value = 100 + (tick % 50) };
        gt_ipc_client_send(light, &reading, now, &events);
        report("light", events, now - start_ms);
        if (tick % 10 == 0) {
            gt_msg soil_reading = { .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_SOIL,
                                    .counter = soil_counter++, .seq = 0, .value = 800 };
            gt_ipc_client_send(soil, &soil_reading, now, &events);
        } else {
            gt_ipc_client_pump(soil, now, &events);
        }
        report("soil", events, now - start_ms);
        uint64_t next_tick = start_ms + (tick + 1) * 100u;
        uint64_t after = mono_ms();
        if (after < next_tick) {
            struct timespec wait = { 0, (long)(next_tick - after) * 1000000L };
            nanosleep(&wait, NULL);
        }
    }
    /* Let both rings drain. */
    for (int tick = 0; tick < 20; tick++) {
        gt_ipc_client_pump(light, mono_ms(), NULL);
        gt_ipc_client_pump(soil, mono_ms(), NULL);
        struct timespec wait = { 0, 100000000L };
        nanosleep(&wait, NULL);
    }
    gt_ipc_stats light_stats, soil_stats;
    gt_ipc_client_stats(light, &light_stats);
    gt_ipc_client_stats(soil, &soil_stats);
    printf("feeder: light made=%u sent=%u queued=%u refused=%u | soil made=%u sent=%u queued=%u refused=%u\n",
           light_counter, light_stats.sent, light_stats.queued, light_stats.refused,
           soil_counter, soil_stats.sent, soil_stats.queued, soil_stats.refused);
    gt_ipc_client_close(light);
    gt_ipc_client_close(soil);
    return 0;
}

